add_shortcode( 'product_reviews_list', 'perfectpixel_product_reviews_shortcode' );

function perfectpixel_product_reviews_shortcode( $atts ) {
	$atts = shortcode_atts( array( 'id' => '', 'limit' => 5, 'min_rating' => 0 ), $atts );
	$args = array(
		'post_type' => 'product',
		'status'    => 'approve',
		'type'      => 'review',
		'number'    => min( 50, max( 1, absint( $atts['limit'] ) ) ),
	);
	$ids = wp_parse_id_list( $atts['id'] );
	if ( $ids ) {
		$args['post__in'] = $ids;
	}
	if ( absint( $atts['min_rating'] ) ) {
		$args['meta_query'] = array( array( 'key' => 'rating', 'value' => absint( $atts['min_rating'] ), 'compare' => '>=', 'type' => 'NUMERIC' ) );
	}
	$reviews = get_comments( $args );
	if ( ! $reviews ) {
		return '';
	}
	$html = '<ul class="perfectpixel-reviews" style="list-style:none;margin:0;padding:0">';
	foreach ( $reviews as $review ) {
		$rating = (int) get_comment_meta( $review->comment_ID, 'rating', true );
		$html  .= '<li style="margin-bottom:1.5em">' . ( $rating ? wc_get_rating_html( $rating ) : '' )
			. '<p>' . esc_html( wp_trim_words( $review->comment_content, 60 ) ) . '</p>'
			. '<p><strong>' . esc_html( $review->comment_author ) . '</strong> · <a href="' . esc_url( get_permalink( $review->comment_post_ID ) ) . '">' . esc_html( get_the_title( $review->comment_post_ID ) ) . '</a></p></li>';
	}
	return '<div class="woocommerce">' . $html . '</ul></div>';
}
